const e="sadm-dance-competition",d=null,t="Built from the 3-page SADM Competition Guidelines PDF. It prints no year, no dates, no venue, no contacts, no entry fee amounts and no way to enter, so those are not captured. The organiser is the Southern Association of Dance Masters (sadm.org). The score band 'High God' is printed that way (it may be a typo for High Gold). The guidelines also name a production category and an Acro or Open category without rules. Placings carry no points in the source.",i={Title:"Rules & Criteria",Subtitle:"SADM dance competition: solos, duets/trios, groups and lines in nine styles. Read these guidelines before you enter.",NoticeTitle:"Please Read Before Registering",Notice:"Music must be sent in MP3 form {{MusicDeadline}}. Entry changes within five days cost {{ChangeFee}}. There are no refunds.",Notes:["The competition line-up: {{LineUpTiming}}.","Times are maximum times. There are no minimum time limits."],Sections:[{Key:"general",Title:"About the Competition",Items:["These guidelines are published by the Southern Association of Dance Masters (SADM) for its dance competition, which is held with the SADM convention.","The nine styles are Ballet, Jazz, Lyrical, Hip Hop, Tap, Contemporary, Musical Theatre, Acrobatics and Modern.","The performance formats are Solo, Duet/Trio, Small Group, Large Group, Line and Grand Line.","SADM, the SADM Dance Competition and the hosting venues are not responsible for loss of property.","The guidelines print no year, no dates and no venue."]},{Key:"eligibility",Title:"Who Can Enter",Items:["Age divisions: Foundations ages 4 to 6, Junior ages 7 to 9, Intermediate ages 10 to 12, Teen ages 13 to 15, Senior ages 16 to 18, and Adult ages 19 and up.","Age divisions are based on the average age of the contestants at the time of the competition.","Ages are rounded up if the average is 0.5 or higher. For example, an average age of 9.5 is placed in the Intermediate division.","Representing teachers and students must be registered for the SADM convention and be present during the competition.","Dancers must wear convention wristbands during performances, except those registered as teachers.","Studio owners and members must be able to show proof of age for each performer if an age protest is made. If they cannot, the routine may be disqualified.","Professional dancers, and anyone who performs or has performed in a professional dance company, may not enter.","Studios and members are limited to a maximum of 10 routines in total, and only 5 of them may be solos.","Each student may enter a maximum of 1 solo."]},{Key:"registration",Title:"How to Enter",Items:["The guidelines do not say where or how entries are sent. Ask the organiser.","Changes made to entries within five days of the competition cost {{ChangeFee}} for each entry changed.","A competition line-up is provided about 1 week before the competition. Line-up timing: {{LineUpTiming}}.","Teachers must make sure their competitors are lined up at the backstage entrance."]},{Key:"fees",Title:"Fees and Refunds",Items:["The guidelines print no entry fee amounts.","There are NO REFUNDS. There are no exceptions.","Changes made to entries within five days of the competition cost {{ChangeFee}} per entry changed.","There is a service fee of {{CardServiceFee}}.","Extra routine time is allowed only for an additional charge: {{ExtraTimeCharge}}."]},{Key:"teams",Title:"Formats and Time Limits",Items:["Solo: time limit 2:30 minutes.","Duet/Trio: time limit 2:30 minutes.","Small Group: 4 to 9 dancers, time limit 2:45 minutes.","Large Group: 10 to 19 dancers, time limit 3:00 minutes.","Line: 20 plus dancers, time limit 5:00 minutes.","Grand Line: 25 plus dancers, time limit 7:00 minutes.","These are maximum times. There are no minimum time limits.","Extra time is subject to additional charges."]},{Key:"judging",Title:"Judging and Scoring",Items:["Scoring criteria: Choreography and Staging 10 points, Musicality and Timing 20 points, Stage Presence and Performance Quality 30 points, Technique 40 points. The total is 100 points.","Judges may deduct points for music lyrics, movements or costumes that are not age appropriate or are inappropriate in the competition setting.","Score bands: Platinum 92 to 100 points, High God 84 to 91 points, Gold 76 to 83 points, Silver 75 points and below.","Judges may give special judges awards at their discretion."]},{Key:"prizes",Title:"Awards",Items:["A 1st place award goes to the solo, duet, trio, group and production category with the highest score in each age division.","2nd and 3rd place awards are given only if there are 10 or more entries in the solo, duet, trio, group and production categories.","One Judges Choice costume award is given at each awards ceremony.","One Judges Choice choreography award is given at each awards ceremony."]},{Key:"conduct",Title:"Conduct and Penalties",Items:["Entrants who leave the stage after their performance begins, for any reason other than a technical one, lose ten points.","No video recording and no flash photography during routines. The first offence is a one-point deduction. Any more violations during a routine lead to disqualification.","Sportsmanlike behaviour is expected from all dancers, teachers and families. Failure to comply may lead to disqualification."]},{Key:"other",Title:"Music and Props",Items:["Music must be submitted in MP3 form {{MusicDeadline}}.","Music must be clean and free of profane content.","Routines have {{PropChangeTime}} to build and remove props.","Props must be brought in and will stay in the staging area. They are not allowed to stay in the wings.","No dangerous props may be used.","Liquids, paints and powders are prohibited.","The scoring text also names a production category and an Acro or Open category, but the guidelines print no rules or time limit for them, so they are not built as competitions."]}],Documents:[{Title:"SADM Competition Guidelines (PDF)",Url:"https://sadm.org/assets/Competition%20Rules.pdf"}]},o=[{ParticipantType:"Individual",Source:"SADM Competition Guidelines, Competition Rules",Sections:{About:null,TimeAndFormat:null,Rules:["A student may enter a maximum of 1 solo.","A studio or member may enter no more than 5 solos in total."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- A student may enter a maximum of 1 solo.
- A studio or member may enter no more than 5 solos in total.`}],n=[],a=[{Title:"Ballet",Source:"SADM Competition Guidelines, Competition Rules",Sections:{About:null,TimeAndFormat:null,Rules:null,Allowed:null,NotAllowed:["No tumbling passes are permitted in the ballet category. An acro or tumbling trick is any time the heel goes over the head."],Judging:null,Points:null,Notes:null},Markdown:`## Not allowed
- No tumbling passes are permitted in the ballet category. An acro or tumbling trick is any time the heel goes over the head.`},{Title:"Acrobatics",Source:"SADM Competition Guidelines, Competition Rules (SADM tumbling rule)",Sections:{About:null,TimeAndFormat:null,Rules:["If a routine has more than 3 tumbling or acro tricks, it is moved to the Acro or Open category.","An acro or tumbling trick is any time the heel goes over the head."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- If a routine has more than 3 tumbling or acro tricks, it is moved to the Acro or Open category.
- An acro or tumbling trick is any time the heel goes over the head.`}],s=[],r=[{Key:"ChangeFee",Kind:"fee",Label:"Fee for a late entry change",Value:"$5.00 per entry changed (changes within five days of the competition)",Source:"SADM Competition Guidelines, Competition Rules"},{Key:"CardServiceFee",Kind:"fee",Label:"Online card payment service fee",Value:"3% on all credit card payments processed online",Source:"SADM Competition Guidelines, Competition Rules"},{Key:"ExtraTimeCharge",Kind:"fee",Label:"Extra routine time",Value:"Extra time is subject to additional charges (amount not printed)",Source:"SADM Competition Guidelines, Competition Guidelines"},{Key:"MusicDeadline",Kind:"text",Label:"Music submission deadline",Value:"MP3 form, 10 days before the competition",Source:"SADM Competition Guidelines, Music"},{Key:"LineUpTiming",Kind:"text",Label:"Competition line-up",Value:"Provided about 1 week before the competition",Source:"SADM Competition Guidelines, Competition Rules"},{Key:"EntryChangeCutoff",Kind:"text",Label:"Entry change cut-off",Value:"Five days before the competition",Source:"SADM Competition Guidelines, Competition Rules"},{Key:"PropChangeTime",Kind:"time",Label:"Time to build and remove props",Value:"1 minute 30 seconds",Source:"SADM Competition Guidelines, Props"}],l=[{Claim:"Registration page content captured from the SADM Competition Guidelines.",SourceType:"Primary - the event's own rules document",Source:"SADM Competition Guidelines",Url:"https://sadm.org/assets/Competition%20Rules.pdf"}],m={TemplateKey:e,Year:null,Note:t,Page:i,ParticipantTypes:o,AgeGroups:n,Competitions:a,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{n as AgeGroups,s as CompetitionAgeGroups,a as Competitions,l as Evidence,t as Note,i as Page,o as ParticipantTypes,e as TemplateKey,r as Variables,d as Year,m as default};
